// library defines it, so carry our own copy of the well-known value. Likewise
// the SDK ships no constant for the 1284 identity query.
static const GUID kUsbPrintInterface = {
    0x28d78fad, 0x5a12, 0x11d1, {0xae, 0x5b, 0x00, 0x00, 0xf8, 0x03, 0xa8, 0xc2}};

