std::shared_ptr<spdlog::logger> logger() {
    // Market sets spdlog's default logger in market::logging::init, so the
    // ported code keeps its spdlog format strings and lands in market-core.log.
    return spdlog::default_logger();
}

std::string toLower(std::string value) {
    for (char& c : value) {
        if (c >= 'A' && c <= 'Z') c = static_cast<char>(c - 'A' + 'a');
    }
    return value;
}

bool contains(std::string_view haystack, std::string_view needle) {
    return haystack.find(needle) != std::string_view::npos;
}

/**
 * Model / driver fragments that mean "thermal receipt printer".
 *
 * Deliberately generous: a false positive only costs one probe page, while a
 * false negative leaves the till unable to print at all.
 */
constexpr std::array<std::string_view, 26> kThermalHints{
    "pos",     "thermal", "receipt", "termal", "58",     "80",      "xp-",
    "xprinter", "tm-",    "epson tm", "star",  "bixolon", "srp-",   "rongta",
    "rp-",     "gprinter", "gp-",    "zj-",    "hprt",   "sam4s",   "citizen",
    "custom",  "generic / text only", "text only", "kassa", "escpos"};

/** Fragments that mean "office printer" - never the till's receipt printer. */
constexpr std::array<std::string_view, 10> kOfficeHints{
    "laserjet", "deskjet", "officejet", "inkjet", "laser",
    "mfp",      "scan",    "photosmart", "ecotank", "a4"};

/**
 * Base score per link kind.
 *
 * `Network` used to sit at 30, below even a bare COM port, so a till whose
 * printer lives on the switch could never win auto-selection. At 45 a raw-print
 * port is worth at least as much as a COM port, and a device that answers
 * `DLE EOT 1` adds `kEscPosConfirmedBonus` on top for 90.
 *
 * That deliberately stays under `UsbRaw`: a USB printer-class device is both
 * certainly a printer and certainly *this* till's printer, whereas a confirmed
 * ESC/POS box on the LAN might belong to the kitchen or the next till over.
 *
 * `Other` drops to 0 so an unrecognised spooler queue is no longer eligible on
 * its own - `deliveryTargets()` only accepts score > 0.
 */
int baseScoreFor(PrinterLink link) {
    switch (link) {
        case PrinterLink::UsbRaw:
            return 100;
        case PrinterLink::UsbQueue:
            return 70;
        case PrinterLink::Network:
            return 45;
        case PrinterLink::Serial:
            return 45;
        case PrinterLink::Lpt:
            return 40;
        case PrinterLink::Other:
            return 0;
        case PrinterLink::Virtual:
            return -50;
    }
    return 0;
}

constexpr int kEscPosConfirmedBonus = 45;
constexpr int kOfflinePenalty = 40;

#ifdef _WIN32
std::string wideToUtf8(const wchar_t* wide) {
    if (!wide) return {};
    const int size = WideCharToMultiByte(CP_UTF8, 0, wide, -1, nullptr, 0, nullptr, nullptr);
    if (size <= 1) return {};
    std::string out(static_cast<std::size_t>(size - 1), '\0');
    WideCharToMultiByte(CP_UTF8, 0, wide, -1, out.data(), size, nullptr, nullptr);
    return out;
}

/** SPDRP_FRIENDLYNAME, falling back to SPDRP_DEVICEDESC. */
std::string deviceName(HDEVINFO set, SP_DEVINFO_DATA& info) {
    for (const DWORD property : {SPDRP_FRIENDLYNAME, SPDRP_DEVICEDESC}) {
        DWORD needed = 0;
        SetupDiGetDeviceRegistryPropertyW(set, &info, property, nullptr, nullptr, 0, &needed);
        if (needed == 0) continue;

        std::vector<BYTE> buffer(needed + sizeof(wchar_t), 0);
        if (SetupDiGetDeviceRegistryPropertyW(set, &info, property, nullptr, buffer.data(), needed,
                                              nullptr)) {
            auto name = wideToUtf8(reinterpret_cast<const wchar_t*>(buffer.data()));
            if (!name.empty()) return name;
        }
    }
    return {};
}

/**
 * Asks the device for its IEEE-1284 identity.
 *
 * Opened read-only and with full sharing so this never steals the handle from
 * an in-flight print job. A device that refuses simply stays unidentified.
 */
std::string queryDeviceId(const std::wstring& devicePath) {
    HANDLE handle = CreateFileW(devicePath.c_str(), GENERIC_READ,
                                FILE_SHARE_READ | FILE_SHARE_WRITE, nullptr, OPEN_EXISTING, 0,
                                nullptr);
    if (handle == INVALID_HANDLE_VALUE) return {};

    std::array<char, 1024> buffer{};
    DWORD returned = 0;
    const BOOL ok = DeviceIoControl(handle, IOCTL_USBPRINT_GET_1284_ID, nullptr, 0, buffer.data(),
                                    static_cast<DWORD>(buffer.size()), &returned, nullptr);
    CloseHandle(handle);
    if (!ok || returned < 2) return {};

    // The reply is prefixed with a big-endian length covering the prefix itself.
    const auto length = static_cast<std::size_t>(
        (static_cast<unsigned char>(buffer[0]) << 8) | static_cast<unsigned char>(buffer[1]));
    const std::size_t available = std::min<std::size_t>(returned, buffer.size());
    if (length <= 2 || length > available) {
        return std::string(buffer.data() + 2, available - 2);
    }
    return std::string(buffer.data() + 2, length - 2);
}
#endif  // _WIN32

