// The sidecar only ever runs on the till, but the pure helpers above are unit
// tested on any host, so the platform calls need non-Windows definitions.
std::vector<PrinterCandidate> discoverUsbPrinters() { return {}; }
std::vector<PrinterCandidate> discoverSerialPorts() { return {}; }
std::vector<PrinterCandidate> discoverSpoolerQueues() { return {}; }
std::vector<std::pair<std::uint32_t, int>> localScanSubnets() { return {}; }
std::vector<std::string> arpCacheHosts() { return {}; }
std::string macForAddress(std::string_view) { return {}; }
std::vector<std::string> printerPortHosts() { return {}; }
std::vector<PrinterCandidate> discoverNetworkPrinters(const NetworkScanOptions&) { return {}; }

#endif  // _WIN32

std::vector<PrinterCandidate> rankPrinterCandidates(const std::string& currentTarget,
                                                    bool includeNetwork) {
    std::vector<PrinterCandidate> all = discoverUsbPrinters();

    for (auto& candidate : discoverSerialPorts()) all.push_back(std::move(candidate));
    for (auto& candidate : discoverSpoolerQueues()) all.push_back(std::move(candidate));

    if (includeNetwork) {
        NetworkScanOptions options;
        if (!currentTarget.empty() && currentTarget != "auto" && currentTarget != "virtual") {
            options.knownTargets.push_back(currentTarget);
        }
        for (auto& candidate : discoverNetworkPrinters(options)) all.push_back(std::move(candidate));
    }

    // A USB device reachable both raw and through a spooler queue is one
    // printer, not two. Keep the raw entry - it works without a driver - but
    // fold the queue's driver name into it so the operator recognises it.
    for (auto& candidate : all) {
        if (candidate.link != PrinterLink::UsbQueue) continue;
        for (auto& raw : all) {
            if (raw.link != PrinterLink::UsbRaw) continue;
            if (raw.driver.empty() && toLower(raw.displayName) == toLower(candidate.displayName)) {
                raw.driver = candidate.driver;
                raw.port = candidate.port;
            }
        }
    }

    PrinterCandidate virtualTarget;
    virtualTarget.target = "virtual";
    virtualTarget.displayName = "Virtual printer (fayla yazır)";
    virtualTarget.link = PrinterLink::Virtual;
    all.push_back(virtualTarget);

    const bool haveCurrent =
        currentTarget.empty() || currentTarget == "auto" ||
        std::any_of(all.begin(), all.end(),
                    [&](const PrinterCandidate& c) { return c.target == currentTarget; });

    if (!haveCurrent) {
        PrinterCandidate configured;
        configured.target = currentTarget;
        configured.displayName = currentTarget;
        configured.link = currentTarget.rfind("tcp:", 0) == 0 ? PrinterLink::Network
                                                              : PrinterLink::Other;
        all.push_back(configured);
    }

    for (auto& candidate : all) {
        candidate.isCurrent = !currentTarget.empty() && candidate.target == currentTarget;
        candidate.score = scoreCandidate(candidate);
    }

    std::stable_sort(all.begin(), all.end(),
                     [](const PrinterCandidate& a, const PrinterCandidate& b) {
                         return a.score > b.score;
                     });
    return all;
}

